        /// The heartbeat's current status. `Paused`: The heartbeat is paused. 'pending': The first request hasn't arrived yet. 'maintenance': The heartbeat is in its maintenance window. 'up': There's no open incident. 'validating': Requests arrive again, and the open incident resolves once the recovery period passes. 'down': A request didn't arrive in time or reported a failure.
        /// </summary>
        [Input("status")]
        public Input<string>? Status { get; set; }

        /// <summary>
        /// Team that owns this heartbeat, such as 't123'. Defaults to the provider's `TeamId`. Set it to create this object in another team. Changing it replaces the resource, because an object can't move to another team.
        /// </summary>
        [Input("teamId")]
        public Input<string>? TeamId { get; set; }

        /// <summary>
        /// Name of the team that owns this heartbeat.
        /// </summary>
        [Input("teamName")]
        public Input<string>? TeamName { get; set; }

        /// <summary>
        /// Seconds to wait before escalating to the whole team. '0' alerts the whole team right away, and null never escalates to the team. Ignored while an escalation policy is set.
        /// </summary>
        [Input("teamWait")]
        public Input<int>? TeamWait { get; set; }

        /// <summary>
        /// When the heartbeat was last updated.
        /// </summary>
        [Input("updatedAt")]
        public Input<string>? UpdatedAt { get; set; }

        [Input("url")]
        private Input<string>? _url;

        /// <summary>
        /// The unique URL your service requests to report a heartbeat. To print it, export it as a stack output and run pulumi stack output with its name and --show-secrets.
        /// </summary>
        public Input<string>? Url
        {
            get => _url;
            set
            {
                var emptySecret = Output.CreateSecret(0);
                _url = Output.Tuple<Input<string>?, int>(value, emptySecret).Apply(t => t.Item1);
            }
        }

        public HeartbeatState()
        {
        }
        public static new HeartbeatState Empty => new HeartbeatState();
    }
}
